select * from jsonb_to_recordset($FIX$[{"id": "1c2453e3-944d-435f-9304-bce43e674ff3", "old_created_at": "2026-10-06 06:13:00+00", "new_created_at": "2026-10-06T16:36:17+00:00", "author_id": "10000000-0000-0000-0000-000000000048", "city_id": "vancouver", "expected_title": "\ubc34\ucfe0\ubc84 \uc0c8 \uc74c\uc218\ub300\uc5d4 \ubb3c\ubcd1 \ucc44\uc6b0\ub294 \uacf3\ub3c4 \ubd99\ub124", "expected_body": "\uc608\uc804\uc5d4 \uae38\uac00 \uc74c\uc218\ub300 \ud558\uba74 \uace0\uac1c \uc219\uc5ec \ub9c8\uc2dc\ub294 \ubaa8\uc591\ubd80\ud130 \ub5a0\uc62c\ub790\ub294\ub370, \uc0c8\ub85c \ub193\ub294 \uac74 \ubb3c\ubcd1 \ucc44\uc6b0\ub294 \uc7a5\uce58\ub3c4 \ubd99\uc74c\n\uae30\uc874 \uc74c\uc218\ub300 \uc911\uc5d4 \uacc4\uc808 \ub530\ub77c \uc26c\ub294 \uac83\ub3c4 \uc788\uc5b4\uc11c, \ubb3c\ubcd1\ub9cc \ub4e4\uace0 \ub098\uac08\uc9c0\ub294 \uc880 \ub354 \uc0dd\uac01 \uc911"}, {"id": "01e8e741-bb7d-4a87-b92c-54b30a9c249f", "old_created_at": "2026-10-06 05:20:00+00", "new_created_at": "2026-10-06T16:29:16+00:00", "author_id": "10000000-0000-0000-0000-000000000051", "city_id": "vancouver", "expected_title": "\ubcf4\ub4dc \ud0c0\ub294 \uc790\ub9ac\ub3c4 \ubcfc\uacfc \uc2a4\ud2b8\ub9ac\ud2b8\ud615\uc774 \ub2e4\ub974\ub124", "expected_body": "\ubcf4\ub4dc \ud0c0\ub294 \uc0ac\ub78c\ub4e4 \uacf5\uac04\uc744 \ucc98\uc74c \uc54c\uc544\ubcf4\ub2c8 \uacf5\uc6d0\ub9c8\ub2e4 \uc0dd\uae40\uc0c8\ubd80\ud130 \ub2e4\ub984\n\ubc34\ucfe0\ubc84 \uc2a4\ucf00\uc774\ud2b8\ud30c\ud06c\uc5d4 \uc6c0\ud479 \ud30c\uc778 \ubcfc\uc774 \uc788\ub294 \uacf3\ub3c4, \uac70\ub9ac\uc758 \ud131 \uac19\uc740 \uad6c\uc870\ub97c \uc62e\uae34 \uc2a4\ud2b8\ub9ac\ud2b8\ud615\ub3c4 \uc788\uc5b4\n\ub09c \uc77c\ub2e8 \ub450 \ubaa8\uc591 \uad6c\ubd84\ud558\ub294 \uac83\ubd80\ud130 \uc775\ud600\ub450\ub824\uace0, \ub3d9\ub124 \uc9c0\ub3c4\uac00 \ub610 \uc870\uae08 \ub113\uc5b4\uc84c\ub124"}, {"id": "438bdcd8-fe96-456a-846e-f6900ee2b6e5", "old_created_at": "2026-10-06 02:16:00+00", "new_created_at": "2026-10-06T16:22:15+00:00", "author_id": "10000000-0000-0000-0000-000000000058", "city_id": "vancouver", "expected_title": "\uc624\ub798\ub41c \uac74\ubb3c \uc8fc\uc18c\ub85c \ubcf4\ub294 \ubc34\ucfe0\ubc84 \uc720\uc0b0 \ubaa9\ub85d", "expected_body": "\uac74\ubb3c \uad6c\uacbd\ud560 \ub54c \uc774\ub984 \ubab0\ub77c\uc11c \uc544\ub294 \ucc99\ub3c4 \ubabb \ud558\uaca0\uc74c \u314b\u314b \uba54\ubaa8 \ub450 \uac1c \ub0a8\uaca8\ub460\n1) \ubc34\ucfe0\ubc84 \uc720\uc0b0 \ubaa9\ub85d\uc740 \uc2dc\uc758\ud68c\uac00 \uc720\uc0b0 \uac00\uce58\ub97c \uc778\uc815\ud55c \uac74\ubb3c\u00b7\uad6c\uc870\ubb3c\uc744 \ubaa8\uc740 \uac70\uace0\n2) \ub3c4\ub85c \uc8fc\uc18c \uc21c\uc73c\ub85c \uc815\ub9ac\ub3fc \uc788\uc5b4\uc11c \uc775\uc219\ud55c \uae38 \uc774\ub984\ubd80\ud130 \uc77d\uc5b4\ubcf4\uba74 \ub35c \ub0af\uc124 \ub4ef"}, {"id": "be3354dd-3833-412b-a1c4-93eb617f49e0", "old_created_at": "2026-10-06 06:46:00+00", "new_created_at": "2026-10-06T16:15:14+00:00", "author_id": "10000000-0000-0000-0000-000000000025", "city_id": "vancouver", "expected_title": "VPL\uc5d4 \uc18c\ub9ac \ub179\uc74c\ud558\uace0 \uc61b \uc0ac\uc9c4 \uc62e\uae30\ub294 \uacf5\uac04\ub3c4 \uc788\ub124", "expected_body": "\ucc45\uc7a5 \uc0ac\uc774\uc5d0\uc11c \uc870\uc6a9\ud788 \uc77d\ub294 \ubaa8\uc2b5\uc774 \ub3c4\uc11c\uad00\uc758 \uc804\ubd80\ucc98\ub7fc \ub290\uaef4\uc9c0\ub358 \ub54c\uac00 \uc788\uc5c8\ub294\ub370\nVPL \uc778\uc2a4\ud53c\ub808\uc774\uc158 \ub7a9\uc740 \uc18c\ub9ac\u00b7\uc601\uc0c1\u00b7\uc0ac\uc9c4\uc744 \ub9cc\ub4e4\uace0 \ubcf4\uc874\ud558\ub294 \uacf5\uac04\uc774\ub124\n\ub179\uc74c\uc2e4\uc774\ub791 \ub514\uc9c0\ud138 \uc81c\uc791\u00b7\uc790\ub8cc \ubcc0\ud658\uc6a9 \uc791\uc5c5\ub300\uac00 \ud568\uaed8 \uc788\uace0\n\uc13c\ud2b8\ub7f4\ub3c4\uc11c\uad00\ubfd0 \uc544\ub2c8\ub77c \uc2a4\ud2b8\ub798\uc2a4\ucf54\ub098 \ubd84\uad00\uc5d0\ub3c4 \uc774\ub7f0 \uacf5\uac04\uc774 \uc788\uc5b4\n\ub098\ub294 \ubb58 \ub0a8\uaca8\ubcf4\uace0 \uc2f6\uc740\uc9c0\ubd80\ud130 \ucc9c\ucc9c\ud788 \uace8\ub77c\ubcfc\uae4c \ud574"}, {"id": "50c89cd7-caca-43b2-8288-4c6f74212351", "old_created_at": "2026-10-05 19:37:00+00", "new_created_at": "2026-10-06T16:08:13+00:00", "author_id": "10000000-0000-0000-0000-000000000066", "city_id": "vancouver", "expected_title": "\uc2a4\uce74\uc774\ud2b8\ub808\uc778 \uc5d8\ub9ac\ubca0\uc774\ud130, \uc788\ub294 \uac83\uacfc \uc6b4\ud589 \uc911\uc778 \uac74 \ub2e4\ub984", "expected_body": "\uacc4\ub2e8 \ub300\uc2e0 \uc5d8\ub9ac\ubca0\uc774\ud130\uac00 \ud544\uc694\ud55c \uc0ac\ub78c\ud55c\ud150 \uc5ed \uc785\uad6c\ubd80\ud130 \ub3d9\uc120\uc774 \ub2ec\ub77c\uc9d0\n\uc2a4\uce74\uc774\ud2b8\ub808\uc778\uc740 \ubaa8\ub4e0 \uc5ed\uc5d0 \uc5d8\ub9ac\ubca0\uc774\ud130\uac00 \uc788\uc5b4\n\ub2e4\ub9cc \uc218\ub9ac \uc911\uc77c \uc218\ub3c4 \uc788\uc5b4\uc11c, \uc5ed\uc5d0 \uc788\ub2e4\ub294 \ub9d0\ub9cc\uc73c\ub85c \uadf8\ub0a0 \uc4f8 \uc218 \uc788\ub2e4\uace0 \ubcf4\uba74 \uc548 \ub428\n\uc774\uc6a9 \uc548\ub0b4\ub294 \ubc14\ub014 \uc218 \uc788\uc73c\ub2c8 \ucd9c\ubc1c \uc804\uc5d0 \uc5d8\ub9ac\ubca0\uc774\ud130 \uc6b4\ud589 \uc54c\ub9bc\uc744 \ud655\uc778\ud574\n\ub09c \ub3d9\uc120 \ubcfc \ub54c \uc774\uac78 \uba3c\uc800 \ub123\uc744 \uac70\uc57c"}, {"id": "d1726bd5-4c12-44b0-8222-d6f4d2bfae47", "old_created_at": "2026-10-06 02:59:00+00", "new_created_at": "2026-10-06T15:47:10+00:00", "author_id": "10000000-0000-0000-0000-000000000070", "city_id": "toronto", "expected_title": "\ud558\uc774\ud30c\ud06c \ub3d9\ubb3c \uc804\uc2dc, 10\uc6d4 13\uc77c\ubd80\ud130 \ud734\uc7a5 \uc608\uc815\uc774\ub124", "expected_body": "\uc544\uc774\ub791 \ub3d9\ubb3c \ubcf4\ub7ec \uac00\ub824\ub294 \uc0ac\ub78c\ub4e4\uc740 \ub2e4\uc74c \uc8fc \uacc4\ud68d\uc774 \ub2ec\ub77c\uc9c8 \uc218\ub3c4 \uc788\uaca0\ub124\n\ud558\uc774\ud30c\ud06c \ub3d9\ubb3c \uc804\uc2dc\ub294 \uc811\uadfc\ub85c \uacf5\uc0ac \ub54c\ubb38\uc5d0 10\uc6d4 13\uc77c\ubd80\ud130 2027\ub144 \ubd04\uae4c\uc9c0 \ub2eb\ub294\ub2e4\uace0 \ub098\uc640 \uc788\uc5b4\n\ub09c \ub2f9\uc7a5 \uc77c\uc815\uc744 \uc815\ud558\uc9c4 \ubabb\ud588\ub294\ub370, \uc774\ucabd \ub300\uc2e0 \uac19\uc774 \ub458\ub7ec\ubcfc \ub9cc\ud55c \uc57c\uc678 \uacf5\uac04\uc740 \uc5b4\ub514\uac00 \uc788\uc744\uae4c?"}, {"id": "0105b63f-00bf-4664-b2a9-67209f8b3b9b", "old_created_at": "2026-10-05 23:17:00+00", "new_created_at": "2026-10-06T15:40:09+00:00", "author_id": "08db325f-9c20-537a-8e88-4418cecf447b", "city_id": "toronto", "expected_title": "\ud1a0\ub860\ud1a0 \uacf5\uc6d0 \uc6b4\ub3d9\uae30\uad6c, \uc0b0\ucc45\uc774\ub791 \ubb36\uc5b4\ubcfc \ub9cc\ud558\ub124", "expected_body": "\uc6b4\ub3d9 \uc2dc\uc791\ud558\ub824\ub2c8 \uac70\ucc3d\ud55c \uacc4\ud68d\ubd80\ud130 \uc138\uc6b0\ub294 \uac8c \uc880 \ubd80\ub2f4\uc2a4\ub7ec\uc6cc\uc11c \uc801\uc5b4\ubd04\n1) \ud1a0\ub860\ud1a0\uc5d4 \uc57c\uc678 \uc6b4\ub3d9\uae30\uad6c\uac00 \uc788\ub294 \uacf5\uc6d0\uc774 \ub530\ub85c \uc788\uc5b4\n2) \ub9ac\ubc84\ub370\uc77c \ud30c\ud06c \uc774\uc2a4\ud2b8\ub791 \uc5bc\uc2a4\ucf54\ud2b8 \ud30c\ud06c\ub3c4 \uadf8 \ubaa9\ub85d\uc5d0 \ub4e4\uc5b4\uac00\uace0\n3) \uc774 \uae30\uad6c\ub4e4\uc744 \uc704\ud55c \uc815\uae30 \uc6b4\ub3d9 \uc218\uc5c5\uc774 \uc7a1\ud600 \uc788\ub294 \uac74 \uc544\ub2c8\ub798\n\ub09c \uc0b0\ucc45\uae38\uc5d0 \uac00\uae4c\uc6b4 \uacf3 \ud558\ub098\ubd80\ud130 \uace8\ub77c\ub450\ub824\uace0"}, {"id": "598ddbae-b747-4588-9b22-2afd4539de16", "old_created_at": "2026-10-05 17:38:00+00", "new_created_at": "2026-10-06T15:19:06+00:00", "author_id": "6aa367e6-70a0-5702-a758-af383ce1503c", "city_id": "montreal", "expected_title": "\ubaac\ud2b8\ub9ac\uc62c \ub3c4\uc11c\uad00 \uc545\uae30 \ubaa9\ub85d\uc5d4 \ud0c0\uc545\uae30\ub3c4 \uc788\ub124", "expected_body": "\uc624\ub798 \ubd99\ub4e4\uace0 \ubcf4\ub294 \ucc45\ub9cc \ub5a0\uc62c\ub9ac\ub358 \ub3c4\uc11c\uad00\uc5d0 \uc545\uae30 \ubaa9\ub85d\ub3c4 \uc788\ub124\n\ubaac\ud2b8\ub9ac\uc62c \ub3c4\uc11c\uad00 \uc545\uae30 \uceec\ub809\uc158\uc5d4 \uae30\ud0c0\u00b7\uc6b0\ucfe8\ub810\ub808 \uac19\uc740 \ud604\uc545\uae30\ubfd0 \uc544\ub2c8\ub77c \uac74\ubc18\uc774\ub791 \ud0c0\uc545\uae30\ub3c4 \ub4e4\uc5b4\uac00 \uc788\uc5b4\n\ub09c \uc6b0\uc120 \uc545\uae30 \uc774\ub984\ubd80\ud130 \uc775\ud600\ub450\ub824\uace0, \ubc30\uc6b0\uace0 \uc2f6\uc740 \uc18c\ub9ac \uace0\ub974\ub294 \uac83\ubd80\ud130 \uc2dc\uc791\ud574\ub3c4 \ub420 \ub4ef"}, {"id": "3cd352fa-a23b-458f-b219-9af37bca6be0", "old_created_at": "2026-10-06 03:16:00+00", "new_created_at": "2026-10-06T14:58:03+00:00", "author_id": "cc3ea647-6ac1-5ffc-ba83-8d4724d2e0f1", "city_id": "montreal", "expected_title": "\ubaac\ud2b8\ub9ac\uc62c \uc9c0\ud558\ub3c4\uc2dc R\u00c9SO, \uc5ed\uacfc \uc1fc\ud551 \uacf5\uac04\uc774 \uc774\uc5b4\uc9c0\ub124", "expected_body": "\uaca8\uc6b8 \ub3d9\uc120 \uc0dd\uac01\ud558\ub2e4\uac00 \uc9c0\ud558\ub3c4\uc2dc R\u00c9SO\ubd80\ud130 \uc0b4\ud3b4\ubcf4\uace0 \uc788\uc5b4\n\ub2e4\uc6b4\ud0c0\uc6b4 \uba54\ud2b8\ub85c\uc5ed\uc774\ub791 \uc1fc\ud551 \uacf5\uac04\uc744 \uc774\uc5b4\uc8fc\ub294 \ubcf4\ud589 \ud1b5\ub85c\ub9dd\uc774\uc57c\n\uac74\ubb3c \ud558\ub098 \uc9c0\ud558\uc0c1\uac00\ub97c \ub9d0\ud558\ub294 \uac8c \uc544\ub2c8\ub77c \uc11c\ub85c \uc5f0\uacb0\ub418\ub294 \uad6c\uc870\ub77c, \ub09c \uc775\uc219\ud55c \uc5ed \uc8fc\ubcc0\ubd80\ud130 \ubcfc \uac70\uc57c\n\ucc98\uc74c \uae38 \uc775\ud790 \ub54c \uc5b4\ub290 \uad6c\uac04\uc774 \ub35c \ud5f7\uac08\ub838\uc5b4?"}, {"id": "138b1e16-06f4-43be-a9c6-4cf6f43aadd6", "old_created_at": "2026-10-06 05:15:00+00", "new_created_at": "2026-10-06T14:51:02+00:00", "author_id": "e64f591a-676e-5778-8a10-fc892105f91c", "city_id": "edmonton", "expected_title": "\uc5d0\ub4dc\uba3c\ud134 \uc57c\uc678 \uc6b4\ub3d9\uae30\uad6c, \ub180\uc774\ud130 \uac00\uae4c\uc6b4 \uc790\ub9ac\ub3c4 \uc788\ub124", "expected_body": "\uacf5\uc6d0\uc5d0\uc11c \uc544\uc774 \uc9c0\ucf1c\ubcf4\ub294 \uc0ac\ub78c\ub3c4 \uc6b4\ub3d9\ud560 \uc218 \uc788\uac8c, \uc5d0\ub4dc\uba3c\ud134\uc5d4 \ub180\uc774\ud130 \uac00\uae4c\uc774\uc5d0 \uc6b4\ub3d9\uae30\uad6c\ub97c \ub454 \uacf3\ub4e4\uc774 \uc788\ub124\n\uc608\uc804\uc5d4 \uc5b4\ub978\uc740 \uc606\uc5d0\uc11c \uae30\ub2e4\ub9ac\ub294 \uadf8\ub9bc\ubd80\ud130 \ub5a0\uc62c\ub838\ub294\ub370 \ub0b4 \uc6b4\ub3d9 \ud551\uacc4\uac00 \ud558\ub098 \uc904\uc5b4\ub4e4\uaca0\uad70 \u314b\u314b"}, {"id": "d1181319-c719-4161-a5b1-5a57c9013eb8", "old_created_at": "2026-10-06 01:11:00+00", "new_created_at": "2026-10-06T14:44:01+00:00", "author_id": "10000000-0000-0000-0000-000000000118", "city_id": "edmonton", "expected_title": "\uc61b \uac00\uac8c \ub124\uc628\uc0ac\uc778\uc774 \uc5d0\ub4dc\uba3c\ud134 \uc57c\uc678 \ubc15\ubb3c\uad00\uc5d0 \ub0a8\uc74c", "expected_body": "\ub124\uc628\uc0ac\uc778\ub3c4 \uac00\uac8c \ub2eb\uc73c\uba74 \uadf8\ub0e5 \uc0ac\ub77c\uc9c0\ub294 \uac74 \uc544\ub2cc \ub4ef\n\uc5d0\ub4dc\uba3c\ud134 \ub124\uc628\uc0ac\uc778 \ubc15\ubb3c\uad00\uc5d4 \ubcf5\uc6d0\ud55c \uc61b \uac04\ud310\ub4e4\uc774\n104\uc2a4\ud2b8\ub9ac\ud2b8 \ucabd \uac74\ubb3c \ubc14\uae65 \ubcbd\uc5d0 \ubaa8\uc5ec \uc788\uc74c"}, {"id": "814c3c1b-0d76-4c7a-95aa-acf0e1fe9845", "old_created_at": "2026-10-06 05:47:00+00", "new_created_at": "2026-10-06T14:37:00+00:00", "author_id": "10000000-0000-0000-0000-000000000110", "city_id": "edmonton", "expected_title": "\ub7f0\ub4e4 \uacf5\uc6d0\uc5d0 \uc6d0\ubc18 \ub358\uc9c0\ub294 \ub514\uc2a4\ud06c\uace8\ud504 \ucf54\uc2a4\ub3c4 \uc788\ub124", "expected_body": "\uc6d0\ubc18 \ub358\uc9c0\ub294 \uc0ac\ub78c \ud558\uba74 \ubc18\ub824\uacac \ub180\uc774\ubd80\ud130 \ub5a0\uc62c\ub9b0 \ub0b4\uac00 \ub108\ubb34 \ub2e8\uc21c\ud588\ub098 \ubd04\n\ub7f0\ub4e4 \uacf5\uc6d0\uc5d4 \ub514\uc2a4\ud06c\uace8\ud504 \ucf54\uc2a4\ub3c4 \uc788\uace0, \uc77c\ubc18 \uace8\ud504 \ucf54\uc2a4\ub791\uc740 \ubcc4\ub3c4\ub85c \uc18c\uac1c\ub3fc \uc788\ub124\n\ub09c \uc774\ub984\ubd80\ud130 \ud5f7\uac08\ub9ac\ub294 \ub2e8\uacc4\ub77c \uc5b4\ub290 \ucabd\uc774 \ub9de\uc744\uc9c0\ub294 \uc544\uc9c1 \ubabb \uace0\ub974\uaca0\uc5b4"}, {"id": "08676e1a-b826-4a30-9879-954289835ac1", "old_created_at": "2026-10-05 19:09:00+00", "new_created_at": "2026-10-06T14:29:59+00:00", "author_id": "10000000-0000-0000-0000-000000000113", "city_id": "edmonton", "expected_title": "\ud038\uc5d8\ub9ac\uc790\ubca0\uc2a4 \uacf5\uc6d0 \uc548 \uc6d0\uc8fc\ubbfc \uc608\uc220\uacf5\uc6d0\ub3c4 \uc54c\uc544\uac00\ub294 \uc911", "expected_body": "\uc5d0\ub4dc\uba3c\ud134 \uacf5\uc6d0\uc740 \uc544\uc9c1 \uc775\ud788\ub294 \uc911\uc778\ub370, \uac77\ub294 \uc0ac\ub78c \uc606\uc5d0 \uc791\ud488\uc774 \ub193\uc774\ub294 \uacf5\uac04\ub3c4 \uc788\ub124\n\ud038\uc5d8\ub9ac\uc790\ubca0\uc2a4 \uacf5\uc6d0 \uc548\uc5d0 \u00ceN\u00ceW \ub9ac\ubc84\ub86f11 \uc6d0\uc8fc\ubbfc \uc608\uc220\uacf5\uc6d0\uc774 \uc788\uc5b4\n\uc774 \ub545\uc758 \uc5ed\uc0ac\uc640 \uc774\uc57c\uae30\ub97c \ub2f4\uc740 \uc870\ud615\ubb3c\uc744 \ubc14\uae65 \uc0b0\ucc45\uae38\uc5d0\uc11c \ub9cc\ub098\ub294 \uacf3\uc774\ub798\n\uc9c0\ub3c4\uc5d0\uc11c \uacf5\uc6d0 \uc774\ub984\ub9cc \uc678\uc6b0\ub2e4 \uacf5\ubd80\ud560 \uac8c \ub298\uc5b4\ub0a8 \u314b\u314b \ub2e4\uc74c\uc5d0 \uac19\uc774 \uac78\uc73c\uba74 \uc791\ud488 \uc598\uae30\ub3c4 \ud574\ubcf4\uc790"}, {"id": "456e394f-9612-4a91-b1c9-eebfca25d67a", "old_created_at": "2026-10-05 18:05:00+00", "new_created_at": "2026-10-06T14:22:58+00:00", "author_id": "10000000-0000-0000-0000-000000000113", "city_id": "edmonton", "expected_title": "\ubc00\ub108\ub3c4\uc11c\uad00 \ub354\ud0a4\uce5c\uc740 \uc694\ub9ac\ub97c \ubc30\uc6b0\ub294 \uacf5\uac04\uc774\ub124", "expected_body": "\ucc98\uc74c\uc5d4 \ub3c4\uc11c\uad00\uc5d0\uc11c \uc694\ub9ac\ud558\ub294 \uc0ac\ub78c \ub5a0\uc62c\ub9ac\uae30\uac00 \uc880 \uc5b4\ub824\uc6e0\uc74c\n\ubc00\ub108\ub3c4\uc11c\uad00\uc758 \ub354\ud0a4\uce5c\uc740 \uc694\ub9ac\u00b7\ubca0\uc774\ud0b9\u00b7\uc74c\uc2dd\uc744 \ubc30\uc6b0\ub294 \uacf5\uac04\uc774\ub124\n\ucc45\uc5d0\uc11c \uc870\ub9ac\ubc95 \uc77d\ub294 \ub370\uc11c \ub05d\ub098\ub294 \uac8c \uc544\ub2c8\ub77c \uc9c1\uc811 \ubc30\uc6b0\ub294 \ucabd\ub3c4 \uc788\ub294 \uac70\uc57c\n\ub098\ub3c4 \ub3d9\ub124 \uc54c\uc544\uac00\ub294 \uae40\uc5d0 \uc774\ub7f0 \uacf3\ubd80\ud130 \uae30\uc5b5\ud574\ub458\ub798, \uac19\uc774 \uac08 \uc0ac\ub78c\ud55c\ud14c \ub3c4\uc11c\uad00 \uc598\uae30 \uaebc\ub0c8\ub2e4\uac00 \ubc30\uace0\ud30c\uc9c8 \ub4ef \u314b\u314b"}, {"id": "6e9c285f-fdf9-4936-9dd5-f5366afbfd3f", "old_created_at": "2026-10-05 18:06:00+00", "new_created_at": "2026-10-06T14:15:57+00:00", "author_id": "10000000-0000-0000-0000-000000000131", "city_id": "calgary", "expected_title": "\ub370\ubcf4\ub2c8\uc548\uac00\ub4e0\uc740 \uac74\ubb3c \uc548\uc5d0\uc11c \uac77\ub294 \uc2dd\ubb3c \uacf5\uac04\uc774\ub124", "expected_body": "\ub370\ubcf4\ub2c8\uc548\uac00\ub4e0 \ucc98\uc74c \uc54c\uc544\ubcf4\ub294\ub370 \uc2e4\ub0b4\uc5d0 \ub098\ubb34\ub791 \uc2dd\ubb3c\uc774 \uc788\uace0 \uc628\ub3c4\ub3c4 \uc870\uc808\ub418\ub294 \uacf5\uac04\uc774\ub124\n\uc1fc\ud551 \uacf5\uac04 \uc704\ucabd\uc5d0 \uc549\uc744 \uc790\ub9ac\ub3c4 \uc788\ub2e4\ub2c8 \uac19\uc774 \uc26c\uae30\uc5d4 \uad1c\ucc2e\uc744 \ub4ef\ud55c\ub370, \uac08 \ub0a0\uc740 \uc544\uc9c1 \ubabb \uc815\ud588\uc5b4"}, {"id": "ed98fa54-c7b1-4ca0-817a-916ba4b3156e", "old_created_at": "2026-10-06 00:54:00+00", "new_created_at": "2026-10-06T14:08:56+00:00", "author_id": "10000000-0000-0000-0000-000000000130", "city_id": "calgary", "expected_title": "\ud50c\ub7ec\uc2a415, \uce98\uac70\ub9ac \uac74\ubb3c \uc0ac\uc774\ub97c \uc2e4\ub0b4\ub85c \uac77\ub294 \uae38\uc774\ub124", "expected_body": "\ub2e4\uc6b4\ud0c0\uc6b4 \ud50c\ub7ec\uc2a415\ub294 \uac74\ubb3c \uc0ac\uc774\ub97c \uc787\ub294 \uc9c0\uc0c1 \ubcf4\ud589 \ud1b5\ub85c\ub9dd\uc774\ub77c \ubc14\uae65 \ub0a0\uc528\ub97c \ud53c\ud558\uba70 \uac78\uc744 \uc218 \uc788\uaca0\ub124\n\ub2eb\ud78c \uc5f0\uacb0 \uad6c\uac04\ub3c4 \uc788\uace0 \uc6b4\uc601 \uc548\ub0b4\ub294 \ubc14\ub014 \uc218 \uc788\uc73c\ub2c8, \uc2e4\uc81c \ub3d9\uc120 \uc7a1\uae30 \uc804\uc5d4 \ub2e4\uc2dc \ud655\uc778\ud574\uc57c\uaca0\uc5b4\n\uc544\uc9c1 \uad6c\uc870\uac00 \uba38\ub9bf\uc18d\uc5d0 \uc548 \uc7a1\ud788\ub294\ub370, \ucc98\uc74c \uc774\uc6a9\ud560 \ub54c \uc5b4\ub514\ubd80\ud130 \uc775\ud614\uc5b4?"}, {"id": "591e437e-24d3-4b8f-902e-8daf1abf6a9c", "old_created_at": "2026-10-05 18:07:00+00", "new_created_at": "2026-10-06T14:01:55+00:00", "author_id": "10000000-0000-0000-0000-000000000141", "city_id": "calgary", "expected_title": "\ubca8\ud2b8\ub77c\uc778 \ub85c\uc774\uc2a4\uc790\ubcf4\ucee4\uba3c\uc2a4\uc5d4 \uc57c\uc678 \ud0c1\uad6c\ub300\uac00 \uc788\ub124", "expected_body": "\ud0c1\uad6c\ub294 \uacf5 \uc8fc\uc6b0\ub7ec \ub6f0\ub294 \uc2dc\uac04\uae4c\uc9c0 \uc6b4\ub3d9\uc5d0 \ub123\uc5b4\uc57c \ud560 \uac83 \uac19\uc74c \u314b\u314b\n\ubca8\ud2b8\ub77c\uc778 \ub85c\uc774\uc2a4\uc790\ubcf4\ucee4\uba3c\uc2a4\uc5d0\ub294 \ucf58\ud06c\ub9ac\ud2b8 \ud0c1\uad6c\ub300\ub791 \uc549\uc544\uc11c \uc26c\ub294 \uacf5\uac04\uc774 \uc788\ub124\n\uc2b9\ubd80\ubcf4\ub2e4 \uac00\ubccd\uac8c \uce58\uace0 \uc26c\ub294 \ucabd\uc774 \ub04c\ub9ac\ub294\ub370, \uc774\ub7f0 \uc57c\uc678 \ud0c1\uad6c \uac19\uc774 \ud574\ubcf4\uba74 \uc5b4\ub54c?"}, {"id": "505fdc8a-f282-4d05-b8e1-2e85331a298f", "old_created_at": "2026-10-05 19:10:00+00", "new_created_at": "2026-10-06T13:54:54+00:00", "author_id": "10000000-0000-0000-0000-000000000128", "city_id": "calgary", "expected_title": "\uba54\ubaa8\ub9ac\uc5bc\ud30c\ud06c\ub3c4\uc11c\uad00\uc5d4 \uc545\uae30 \ub300\uc5ec\ub791 \uc5f0\uc2b5\uc2e4\ub3c4 \uc788\ub124", "expected_body": "\uae30\ud0c0 \ubc30\uc6b0\ub824\uba74 \uc77c\ub2e8 \ub0b4 \uc545\uae30\ubd80\ud130 \uc0ac\uc57c \ud55c\ub2e4\uace0 \uc0dd\uac01\ud588\ub294\ub370\n\uba54\ubaa8\ub9ac\uc5bc\ud30c\ud06c\ub3c4\uc11c\uad00\uc5d4 \uae30\ud0c0\u00b7\uac74\ubc18\u00b7\ud0c0\uc545\uae30 \uac19\uc740 \uc545\uae30\ub97c \ube4c\ub9ac\ub294 \uceec\ub809\uc158\uc774 \uc788\uc74c\n\uc74c\uc545 \uc5f0\uc2b5\uc2e4\ub3c4 \ub530\ub85c \uc788\uc5b4\uc11c \uc545\uae30 \ubaa9\ub85d\uc774\ub791 \uacf5\uac04\uc744 \uac19\uc774 \ubcfc \uc218 \uc788\uc5b4\n\uc608\uc804\uc5d4 \uc545\uae30 \uc774\ub984\ub9cc \uc5f4\uc2ec\ud788 \uc678\uc6e0\ub294\ub370 \uc774\ubc88\uc5d4 \uc18c\ub9ac\ubd80\ud130 \uace8\ub77c\ubcfc \uac70\uc57c, \uc7a5\ubc14\uad6c\ub2c8\ub9cc \uc5f0\uc8fc\ud560 \uc21c \uc5c6\uc796\uc544 \u314b\u314b"}, {"id": "3533eb91-f780-4bc8-b33b-f9a0979fa675", "old_created_at": "2026-10-05 19:42:00+00", "new_created_at": "2026-10-06T13:47:53+00:00", "author_id": "10000000-0000-0000-0000-000000000128", "city_id": "calgary", "expected_title": "\ub784\ud504\ud074\ub77c\uc778\uacf5\uc6d0 \uc2b5\uc9c0\ub294 \ube57\ubb3c\uc744 \ucc98\ub9ac\ud558\ub294 \uacf3\uc774\uae30\ub3c4 \ud568", "expected_body": "\ubb3c\uc740 \uacf5\uc6d0 \ud48d\uacbd\uc778 \uc904\ub9cc \uc54c\uc558\ub294\ub370 \ub784\ud504\ud074\ub77c\uc778\uacf5\uc6d0\uc5d0\uc120 \uc5ed\ud560\uc774 \ub354 \uc788\uc74c\n\uc5ec\uae34 \ube57\ubb3c\uc744 \ucc98\ub9ac\ud558\ub824\uace0 \ub9cc\ub4e0 \uc778\uacf5 \uc2b5\uc9c0 \uc8fc\ubcc0\uc73c\ub85c \uc0b0\ucc45\uae38\uc774 \uc774\uc5b4\uc838\n\uc790\uc5f0\ub180\uc774\ud130\ub3c4 \uc0b0\uc5d0\uc11c \uc2b5\uc9c0\uae4c\uc9c0 \ubb3c\uc774 \uc774\ub3d9\ud558\ub294 \ud750\ub984\uc744 \uc8fc\uc81c\ub85c \ub9cc\ub4e4\uc5c8\ub300\n\uc5b4\ub9b4 \ub54c \ubb3c\uae38 \ub0b8\ub2f5\uc2dc\uace0 \ubaa8\ub798\ub9cc \ud320\ub294\ub370 \uc774\ucabd\uc740 \uc81c\ub300\ub85c \ubb3c \uacf5\ubd80\ud558\ub294 \uacf5\uac04\uc774\ub124 \u314b\u314b\n\ub2e4\uc74c\uc5d4 \uc2dd\ubb3c \uc774\ub984\ub9cc \ubcf4\uc9c0 \ub9d0\uace0 \ubb3c\uc774 \uc5b4\ub514\ub85c \uc774\uc5b4\uc9c0\ub294\uc9c0\ub3c4 \ubcfc \uac70\uc57c"}]$FIX$::jsonb)
as x(id uuid,old_created_at timestamptz,new_created_at timestamptz,author_id uuid,city_id text,expected_title text,expected_body text);
do $$ begin
 perform 1 from public.posts p join city_date_fix f on f.id=p.id for update of p;
 if (select count(*) from public.posts p join city_date_fix f on f.id=p.id
     join public.profiles pr on pr.id=p.author_id join auth.users u on u.id=pr.id
     where p.created_at=f.old_created_at and p.author_id=f.author_id and p.city_id=f.city_id
       and p.title=f.expected_title and p.body=f.expected_body and p.status='published'
       and pr.city_id=p.city_id and u.email like '%@seed.gling.invalid') <> 19 then
   raise exception 'CITY_DATE_FIX_CONCURRENT_CHANGE';
 end if;
end $$;
update public.posts p set created_at=f.new_created_at,posted_on=date '2026-10-06'
from city_date_fix f where p.id=f.id;
update private.post_view_pulse pulse
set bucket=date_bin(interval '10 minutes',f.new_created_at,'2000-01-01'::timestamptz)
from city_date_fix f
where pulse.post_id=f.id and pulse.bucket=date_bin(interval '10 minutes',f.old_created_at,'2000-01-01'::timestamptz);
commit;
